#include "installer.hpp"
#include "vga_font.hpp"
#include "space_mono_font.hpp"   // generated by ttf_to_vga_font.py -- see README
#include "../../compositor/src/window.hpp"
#include "../../compositor/src/surface.hpp"
#include "../../../zanop-kernel/src/drivers/vga.hpp"
// NOTE on includes above: relative paths assume the sibling-folder
// layout used throughout this project (zanop-kernel, zanop-desktop-os
// as siblings). Also NOTE: the keyboard driver's actual current
// namespace/API hasn't been shown to me this session -- I'm assuming
// `Drivers::Keyboard::` matching what main.cpp used earlier, but this
// is unverified. If the real keyboard.hpp differs, this file will
// need the same kind of namespace fix serial.cpp and vga.cpp needed.
#include "../../../zanop-kernel/src/drivers/keyboard.hpp"

namespace installer {
namespace {

constexpr std::uint8_t SC_ENTER = 0x1C;
constexpr std::uint8_t SC_ESC   = 0x01;
constexpr std::uint8_t SC_SPACE = 0x39;
constexpr std::uint8_t SC_1     = 0x02;
constexpr std::uint8_t SC_2     = 0x03;
constexpr std::uint8_t SC_3     = 0x04;

enum class Step { Welcome, License, SetupType, UserInfo, Installing, Finish };

bool license_agreed = false;
int setup_type_choice = 1; // 1=Typical, 2=Custom, 3=Minimal
char username[32] = "User";
std::size_t username_len = 4;

std::uint8_t wait_key() {
    return Drivers::Keyboard::read_scancode();
}

// Simple in-window text field editor -- echoes typed characters at a
// fixed screen position via the compositor surface, since there's no
// shared line-editor exposed outside the kernel shell/apps yet.
void edit_field(std::size_t col, std::size_t row, char* buf, std::size_t max_len, std::size_t& len) {
    surface::fill_rect(col, row, max_len + 1, 1, ' ');
    surface::put_str(col, row, buf);
    while (true) {
        std::uint8_t sc = Drivers::Keyboard::read_scancode();
        if (sc == SC_ENTER) return;
        auto ascii = Drivers::Keyboard::scancode_to_ascii(sc);
        if (!ascii) continue;
        char c = *ascii;
        if (c == 0x08) { // backspace
            if (len > 0) { --len; buf[len] = '\0'; }
        } else if (len < max_len - 1) {
            buf[len++] = c;
            buf[len] = '\0';
        }
        surface::fill_rect(col, row, max_len + 1, 1, ' ');
        surface::put_str(col, row, buf);
    }
}

void draw_button_row(const char* hint) {
    surface::fill_rect(0, surface::SCREEN_HEIGHT - 1, surface::SCREEN_WIDTH, 1, ' ');
    surface::put_str(2, surface::SCREEN_HEIGHT - 1, hint);
}

void screen_welcome() {
    compositor::Window win("Zanop Desktop OS Setup", 10, 4, 60, 14);
    win.set_body_line(0, "Welcome to the Zanop Desktop OS Setup program.");
    win.set_body_line(2, "This program will install Zanop Desktop OS on");
    win.set_body_line(3, "your computer.");
    win.set_body_line(5, "It is strongly recommended that you close any");
    win.set_body_line(6, "other programs before continuing.");
    win.set_body_line(8, "Press Enter to continue, or Esc to exit Setup.");
    win.draw();
    draw_button_row("[Enter] Next    [Esc] Cancel");
}

void screen_license() {
    compositor::Window win("License Agreement", 10, 4, 60, 14);
    win.set_body_line(0, "ZANOP DESKTOP OS - SOFTWARE LICENSE AGREEMENT");
    win.set_body_line(2, "By continuing, you accept the terms of this");
    win.set_body_line(3, "agreement. Provided as-is, for development and");
    win.set_body_line(4, "testing purposes. See LICENSE for full terms.");
    win.set_body_line(6, license_agreed ? "[X] I Agree to the License Agreement"
                                          : "[ ] I Agree to the License Agreement");
    win.set_body_line(8, "Press Space to toggle agreement.");
    win.draw();
    draw_button_row(license_agreed ? "[Enter] Next    [Esc] Back"
                                     : "Space to agree first    [Esc] Back");
}

void screen_setup_type() {
    compositor::Window win("Setup Type", 10, 4, 60, 14);
    win.set_body_line(0, "Choose the setup type that best suits your needs.");
    win.set_body_line(2, setup_type_choice == 1 ? "> 1. Typical  (most common options)"
                                                  : "  1. Typical  (most common options)");
    win.set_body_line(3, setup_type_choice == 2 ? "> 2. Custom   (choose components)"
                                                  : "  2. Custom   (choose components)");
    win.set_body_line(4, setup_type_choice == 3 ? "> 3. Minimal  (base system + shell only)"
                                                  : "  3. Minimal  (base system + shell only)");
    win.set_body_line(6, "Press 1, 2, or 3 to select.");
    win.draw();
    draw_button_row("[Enter] Next    [Esc] Back");
}

void screen_user_info() {
    compositor::Window win("User Information", 10, 4, 60, 14);
    win.set_body_line(0, "Enter your name below, then press Enter.");
    win.draw();
    draw_button_row("Type your name, [Enter] to confirm    [Esc] Back");
    // window body starts 3 rows below the window's y (title + divider),
    // and 2 cols in from the window's x -- matches Window::draw()'s layout
    edit_field(10 + 2, 4 + 3, username, sizeof(username), username_len);
}

void screen_installing() {
    compositor::Window win("Installing Zanop Desktop OS", 10, 4, 60, 14);
    win.set_body_line(0, "Please wait while Setup copies files...");
    win.draw();
    draw_button_row("Please wait...");

    char bar[41];
    for (int pct = 0; pct <= 40; ++pct) {
        for (int i = 0; i < 40; ++i) bar[i] = (i < pct) ? '#' : '.';
        bar[40] = '\0';
        surface::fill_rect(10 + 2, 4 + 5, 42, 1, ' ');
        surface::put_str(10 + 2, 4 + 5, bar);
        for (volatile int d = 0; d < 800000; ++d) {} // crude delay, no timer yet
    }
}

void screen_finish() {
    compositor::Window win("Setup Complete", 10, 4, 60, 14);
    win.set_body_line(0, "Zanop Desktop OS has been successfully installed.");
    win.set_body_line(2, "Press Enter to restart, or Esc to exit Setup.");
    win.draw();
    draw_button_row("[Enter] Restart    [Esc] Exit");
}

} // namespace

void run() {
    vga_font::load(vga_font::SPACE_MONO_FONT);
    VGA::init();

    Step step = Step::Welcome;

    while (true) {
        VGA::writer.clear_screen();

        switch (step) {
            case Step::Welcome:    screen_welcome();     break;
            case Step::License:    screen_license();     break;
            case Step::SetupType:  screen_setup_type();  break;
            case Step::UserInfo:   screen_user_info();   break;
            case Step::Installing: screen_installing();  break;
            case Step::Finish:     screen_finish();      break;
        }

        if (step == Step::Installing) {
            step = Step::Finish;
            continue;
        }
        if (step == Step::UserInfo) {
            // edit_field already consumed the confirming Enter itself
            step = Step::Installing;
            continue;
        }

        std::uint8_t sc = wait_key();

        if (step == Step::License && sc == SC_SPACE) {
            license_agreed = !license_agreed;
            continue;
        }
        if (step == Step::SetupType) {
            if (sc == SC_1) { setup_type_choice = 1; continue; }
            if (sc == SC_2) { setup_type_choice = 2; continue; }
            if (sc == SC_3) { setup_type_choice = 3; continue; }
        }

        if (sc == SC_ENTER) {
            if (step == Step::License && !license_agreed) continue; // blocked
            if (step == Step::Finish) return; // done -- hand back to caller
            step = static_cast<Step>(static_cast<int>(step) + 1);
        } else if (sc == SC_ESC) {
            if (step == Step::Welcome) return; // cancel setup entirely
            step = static_cast<Step>(static_cast<int>(step) - 1);
        }
    }
}

} // namespace installer
